<?php require __DIR__.'/../bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)post('id');$status=(string)post('status');$plan=(string)post('plan');if(in_array($status,['approved','rejected'],true)){db()->prepare('UPDATE subscription_requests SET status=?,admin_note=?,updated_at=NOW() WHERE id=?')->execute([$status,trim((string)post('note','')),$id]);if($status==='approved'&&in_array($plan,['basic','premium'],true)){db()->prepare('UPDATE users u JOIN subscription_requests r ON r.user_id=u.id SET u.plan=? WHERE r.id=?')->execute([$plan,$id]);}}redirect('/admin/billing/');}$rows=db()->query('SELECT r.*,u.full_name,u.email FROM subscription_requests r JOIN users u ON u.id=r.user_id ORDER BY r.created_at DESC')->fetchAll();$title='Billing Requests';require __DIR__.'/../includes/header.php';?><div class="page-head"><div><span class="eyebrow">Administration</span><h1>Billing Requests</h1><p>Verify waiting tokens and manually activate Basic/Premium plans.</p></div></div><div class="card table-wrap"><table><tr><th>Customer</th><th>Plan</th><th>Amount</th><th>Method</th><th>Waiting Token</th><th>Status</th><th>Proof</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?><br><small><?=e($r['email'])?></small></td><td><?=e($r['plan'])?></td><td>$<?=e($r['amount'])?></td><td><?=e($r['payment_method'])?></td><td><code><?=e($r['waiting_token'])?></code></td><td><?=e($r['status'])?></td><td><?php if($r['proof_path']):?><a class="btn small secondary" href="<?=e($r['proof_path'])?>" target="_blank">View</a><?php else:?>—<?php endif;?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="plan" value="<?=e($r['plan'])?>"><input name="note" placeholder="Note"><div class="actions"><button class="btn small" name="status" value="approved">Approve</button><button class="btn small danger" name="status" value="rejected">Reject</button></div></form></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../includes/footer.php'; ?>